/**
 * Every URL on the site. Nothing reaches Google until someone submits it from Content indexing or Indexing -- new rows arrive as Not submitted, which means search engines may crawl the page but are told not to list it.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "page-index".
 */
export interface PageIndex {
  id: number;
  /**
   * Stable key set by the scan (computed: type:service:state:city, entity: type:docId). Not hand-editable.
   */
  pageKey: string;
  /**
   * The live URL this row controls.
   */
  path: string;
  pageType:
    | 'service-pillar'
    | 'service-state'
    | 'service-city'
    | 'state-hub'
    | 'city-hub'
    | 'brand-pillar'
    | 'brand-state'
    | 'brand-city-directory'
    | 'clinic'
    | 'guide'
    | 'news'
    | 'static'
    | 'question';
  /**
   * Not submitted (default): search engines can crawl the page but are told not to list it, and it is waiting for a batch. Submitted: it goes into the sitemap as soon as it is live on the site. Never submit: held back permanently, and the batch tools skip it.
   */
  indexMode: 'queued' | 'indexed' | 'excluded';
  /**
   * The answer both the page tag and the sitemap use. Only true when someone submitted it AND it is live on the site.
   */
  indexed?: boolean | null;
  /**
   * Is there anything real to show here? For a clinic, guide or article: the document is published (and approved). For a listing page: at least one published clinic matches it. Written by the scan. When this is false the page stays out of Google no matter what anyone sets above.
   */
  publishable?: boolean | null;
  /**
   * Does this page have enough behind it to be worth a search result? Bar per page type: service-city 5, brand-city-directory 5, city-hub 5, service-state 10, brand-state 10, state-hub 10, service-pillar 25, brand-pillar 25, clinic 1, guide 1, news 1, static 1, question 1. Advice only, not a block: a thin page can still be submitted on purpose.
   */
  meetsThreshold?: boolean | null;
  /**
   * When this URL was batched in. Empty while queued or excluded.
   */
  indexedAt?: string | null;
  /**
   * Which batch flipped this row to Indexed. Filter on it to review or roll back one batch.
   */
  batchLabel?: string | null;
  /**
   * For entity pages: the collection the URL comes from. Empty for computed pages.
   */
  sourceCollection?: string | null;
  /**
   * For entity pages: the source document id, so this row links back to the doc.
   */
  sourceId?: string | null;
  serviceSlug?: string | null;
  brandSlug?: string | null;
  stateSlug?: string | null;
  citySlug?: string | null;
  /**
   * Published clinics matching this page at the last scan. Entity pages carry 1 (they are gated by publish status, not volume).
   */
  dataCount?: number | null;
  hasData?: boolean | null;
  /**
   * Triage flag. Newly discovered URLs land unacknowledged so they show up as "new since you last looked". Batching a row in or excluding it acknowledges it automatically; you can also acknowledge to mean "seen, leaving it queued for now".
   */
  acknowledged?: boolean | null;
  firstSeenWithData?: string | null;
  lastScannedAt?: string | null;
  updatedAt: string;
  createdAt: string;
}
